BEGIN;
CREATE TABLE public.creator_comment_holds(comment_id uuid PRIMARY KEY REFERENCES public.post_comments(id) ON DELETE CASCADE,trainer_id uuid NOT NULL REFERENCES auth.users(id),hidden boolean NOT NULL,reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 500),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.creator_comment_holds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.creator_comment_holds FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.creator_comment_holds TO service_role;
GRANT SELECT ON public.creator_comment_holds TO authenticated;
CREATE POLICY own_comment_holds ON public.creator_comment_holds FOR SELECT TO authenticated USING(trainer_id=auth.uid() OR has_role(auth.uid(),'admin'));
CREATE FUNCTION public.creator_comment_visible(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT NOT EXISTS(SELECT 1 FROM creator_comment_holds WHERE comment_id=p_id AND hidden AND trainer_id IS DISTINCT FROM auth.uid() AND NOT has_role(auth.uid(),'admin')) $$;
CREATE POLICY creator_comment_hold_guard ON public.post_comments AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(creator_comment_visible(id));
CREATE FUNCTION public.moderate_creator_comment(p_id uuid,p_hidden boolean,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t uuid;BEGIN SELECT p.author_id INTO t FROM post_comments c JOIN posts p ON p.id=c.post_id WHERE c.id=p_id;IF t IS NULL OR t<>auth.uid() OR NOT account_can_act(auth.uid(),false) OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=t AND role='trainer') THEN RAISE EXCEPTION 'Only the trainer who owns this post may moderate its comments';END IF;INSERT INTO creator_comment_holds(comment_id,trainer_id,hidden,reason) VALUES(p_id,t,p_hidden,p_reason) ON CONFLICT(comment_id) DO UPDATE SET hidden=excluded.hidden,reason=excluded.reason,updated_at=now();INSERT INTO moderation_actions(actor_id,target_type,target_id,action,note) VALUES(auth.uid(),'comment',p_id::text,CASE WHEN p_hidden THEN 'trainer_hidden' ELSE 'trainer_restored' END,p_reason);END $$;
CREATE FUNCTION public.reply_creator_comment(p_id uuid,p_text text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE post uuid;t uuid;result uuid;BEGIN SELECT p.id,p.author_id INTO post,t FROM post_comments c JOIN posts p ON p.id=c.post_id WHERE c.id=p_id;IF t IS DISTINCT FROM auth.uid() OR NOT account_can_act(auth.uid(),true) OR NOT can_see_trybe((SELECT trybe FROM posts WHERE id=post)) OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND role='trainer') THEN RAISE EXCEPTION 'Authorized trainer post owner required';END IF;PERFORM pg_advisory_xact_lock(hashtext('comment-reply:'||auth.uid()));IF (SELECT count(*) FROM post_comments WHERE author_id=auth.uid() AND created_at>now()-interval '1 minute')>=20 THEN RAISE EXCEPTION 'Please wait before replying again';END IF;INSERT INTO post_comments(post_id,author_id,author_name,text) SELECT post,auth.uid(),name,trim(p_text) FROM profiles WHERE id=auth.uid() RETURNING id INTO result;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.creator_comment_visible(uuid),public.moderate_creator_comment(uuid,boolean,text),public.reply_creator_comment(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.creator_comment_visible(uuid) TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.moderate_creator_comment(uuid,boolean,text),public.reply_creator_comment(uuid,text) TO authenticated;
CREATE TABLE public.workout_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),video_id uuid NOT NULL REFERENCES public.trainer_videos(id),author_id uuid NOT NULL REFERENCES auth.users(id),author_name text NOT NULL,text text NOT NULL CHECK(length(trim(text)) BETWEEN 1 AND 1000),parent_id uuid REFERENCES public.workout_comments(id),hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX workout_comment_thread ON public.workout_comments(video_id,created_at);
CREATE FUNCTION public.workout_comment_access(p_user uuid,p_video uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT (p_user=auth.uid() OR current_setting('role',true) NOT IN ('anon','authenticated')) AND p_user IS NOT NULL AND (has_role(p_user,'admin') OR EXISTS(SELECT 1 FROM trainer_videos v WHERE v.id=p_video AND (v.user_id=p_user OR (account_can_act(p_user,false) AND feedback_can_access(p_user,p_video) AND EXISTS(SELECT 1 FROM trybe_memberships WHERE user_id=p_user AND trybe_id='coach-'||v.user_id))))) $$;
ALTER TABLE public.workout_comments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.workout_comments FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.workout_comments TO service_role;
GRANT SELECT ON public.workout_comments TO authenticated;
CREATE POLICY workout_comment_read ON public.workout_comments FOR SELECT TO authenticated USING(workout_comment_access(auth.uid(),video_id) AND (NOT hidden OR author_id=auth.uid() OR has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM trainer_videos WHERE id=video_id AND user_id=auth.uid())));
CREATE FUNCTION public.save_workout_comment(p_video uuid,p_text text,p_parent uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result uuid;t uuid;BEGIN IF NOT workout_comment_access(auth.uid(),p_video) OR NOT account_can_act(auth.uid(),true) OR (p_parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workout_comments WHERE id=p_parent AND video_id=p_video AND parent_id IS NULL AND NOT hidden)) THEN RAISE EXCEPTION 'Join the trainer Trybe and obtain authorized workout access before commenting';END IF;PERFORM pg_advisory_xact_lock(hashtext('workout-comment:'||auth.uid()));IF (SELECT count(*) FROM workout_comments WHERE author_id=auth.uid() AND created_at>now()-interval '1 minute')>=20 THEN RAISE EXCEPTION 'Please wait before commenting';END IF;INSERT INTO workout_comments(video_id,author_id,author_name,text,parent_id) SELECT p_video,auth.uid(),name,trim(p_text),p_parent FROM profiles WHERE id=auth.uid() RETURNING id INTO result;SELECT user_id INTO t FROM trainer_videos WHERE id=p_video;IF t<>auth.uid() THEN PERFORM creator_notify(t,'workout-comment:'||result,'A member commented on your workout.','/studio?section=content-library');END IF;RETURN result;END $$;
CREATE FUNCTION public.moderate_workout_comment(p_id uuid,p_hidden boolean,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT account_can_act(auth.uid(),false) OR length(trim(p_reason)) NOT BETWEEN 3 AND 500 OR NOT EXISTS(SELECT 1 FROM workout_comments c JOIN trainer_videos v ON v.id=c.video_id WHERE c.id=p_id AND v.user_id=auth.uid()) THEN RAISE EXCEPTION 'Workout owner and a moderation reason required';END IF;UPDATE workout_comments SET hidden=p_hidden WHERE id=p_id;INSERT INTO moderation_actions(actor_id,target_type,target_id,action,note) VALUES(auth.uid(),'workout_comment',p_id::text,CASE WHEN p_hidden THEN 'hidden' ELSE 'restored' END,p_reason);END $$;
REVOKE ALL ON FUNCTION public.workout_comment_access(uuid,uuid),public.save_workout_comment(uuid,text,uuid),public.moderate_workout_comment(uuid,boolean,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.workout_comment_access(uuid,uuid) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_workout_comment(uuid,text,uuid),public.moderate_workout_comment(uuid,boolean,text) TO authenticated;
COMMIT;
